CREATE DATABASE IF NOT EXISTS misalud_db CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE misalud_db;
CREATE TABLE IF NOT EXISTS usuarios(id INT AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(90) NOT NULL,apellido_paterno VARCHAR(90) NOT NULL,apellido_materno VARCHAR(90) NOT NULL,correo VARCHAR(190) NOT NULL UNIQUE,telefono VARCHAR(10) NOT NULL,password_hash VARCHAR(255) NOT NULL,rol ENUM('paciente','medico','admin') NOT NULL,activo TINYINT(1) NOT NULL DEFAULT 1,creado_en TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS especialidades(id INT AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(100) NOT NULL UNIQUE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS consultorios(id INT AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(100) NOT NULL UNIQUE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS pacientes(id INT AUTO_INCREMENT PRIMARY KEY,usuario_id INT NOT NULL UNIQUE,curp CHAR(18) NOT NULL UNIQUE,fecha_nacimiento DATE NOT NULL,peso DECIMAL(5,1) NULL,altura DECIMAL(3,2) NULL,sexo VARCHAR(30) NULL,domicilio VARCHAR(250) NULL,ocupacion VARCHAR(120) NULL,contacto_emergencia_nombre VARCHAR(150) NULL,contacto_emergencia_telefono VARCHAR(20) NULL,FOREIGN KEY(usuario_id) REFERENCES usuarios(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS medicos(id INT AUTO_INCREMENT PRIMARY KEY,usuario_id INT NOT NULL UNIQUE,curp CHAR(18) NOT NULL UNIQUE,cedula VARCHAR(8) NOT NULL UNIQUE,especialidad_id INT NULL,consultorio_id INT NULL,verificado TINYINT(1) NOT NULL DEFAULT 0,telefono_emergencia VARCHAR(20) NULL,domicilio VARCHAR(250) NULL,fecha_nacimiento DATE NULL,foto_perfil VARCHAR(60) NULL,cedula_documento VARCHAR(60) NULL,direccion_calle VARCHAR(100) NULL,direccion_numero_exterior VARCHAR(20) NULL,direccion_numero_interior VARCHAR(20) NULL,direccion_colonia VARCHAR(80) NULL,direccion_codigo_postal VARCHAR(5) NULL,direccion_municipio VARCHAR(80) NULL,direccion_estado VARCHAR(80) NULL,FOREIGN KEY(usuario_id) REFERENCES usuarios(id),FOREIGN KEY(especialidad_id) REFERENCES especialidades(id),FOREIGN KEY(consultorio_id) REFERENCES consultorios(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS horarios_medicos(id INT AUTO_INCREMENT PRIMARY KEY,medico_id INT NOT NULL,dia_semana TINYINT NOT NULL,inicio TIME NOT NULL,fin TIME NOT NULL,FOREIGN KEY(medico_id) REFERENCES medicos(id),CONSTRAINT chk_dia CHECK(dia_semana BETWEEN 1 AND 7),CONSTRAINT chk_horas CHECK(inicio<fin)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS citas(id INT AUTO_INCREMENT PRIMARY KEY,paciente_id INT NOT NULL,medico_id INT NOT NULL,consultorio_id INT NULL,fecha DATE NOT NULL,hora TIME NOT NULL,estado ENUM('programada','atendida','cancelada') NOT NULL DEFAULT 'programada',ocupacion_activa TINYINT GENERATED ALWAYS AS (CASE WHEN estado='programada' THEN 1 ELSE NULL END) STORED,creado_en TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY cita_unica_medico(medico_id,fecha,hora,ocupacion_activa),UNIQUE KEY cita_unica_paciente(paciente_id,fecha,hora,ocupacion_activa),FOREIGN KEY(paciente_id) REFERENCES pacientes(id),FOREIGN KEY(medico_id) REFERENCES medicos(id),FOREIGN KEY(consultorio_id) REFERENCES consultorios(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS recetas(id INT AUTO_INCREMENT PRIMARY KEY,cita_id INT NOT NULL UNIQUE,contenido TEXT NOT NULL,creado_en TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(cita_id) REFERENCES citas(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS turnos_virtuales(id INT AUTO_INCREMENT PRIMARY KEY,paciente_id INT NOT NULL,fecha DATE NOT NULL,estado ENUM('en_espera','atendido','cancelado') NOT NULL DEFAULT 'en_espera',creado_en TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(paciente_id) REFERENCES pacientes(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS donaciones(id INT AUTO_INCREMENT PRIMARY KEY,paciente_id INT NOT NULL,tipo VARCHAR(100) NOT NULL,descripcion VARCHAR(1000) NOT NULL,estado ENUM('registrada','aceptada','entregada') NOT NULL DEFAULT 'registrada',creado_en TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(paciente_id) REFERENCES pacientes(id)) ENGINE=InnoDB;
INSERT IGNORE INTO especialidades(nombre) VALUES('Medicina general'),('Pediatría'),('Cardiología'),('Dermatología'),('Ginecología'),('Neurología'),('Nutrición'),('Psicología'),('Oftalmología'),('Traumatología'),('Endocrinología'),('Otorrinolaringología');
INSERT IGNORE INTO consultorios(nombre) VALUES('Consultorio 101'),('Consultorio 102'),('Consultorio 103'),('Consultorio 104'),('Consultorio 105'),('Consultorio 106');


CREATE TABLE IF NOT EXISTS planes_servicio (id INT AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(70) NOT NULL UNIQUE,limite_bytes BIGINT UNSIGNED NOT NULL,descripcion VARCHAR(200) NOT NULL DEFAULT '') ENGINE=InnoDB;
INSERT IGNORE INTO planes_servicio (nombre,limite_bytes,descripcion) VALUES ('Inicial',104857600,'100 MB · capacidad de demostración'),('Avanzado',1073741824,'1 GB · capacidad de demostración'),('Institucional',5368709120,'5 GB · capacidad de demostración');
CREATE TABLE IF NOT EXISTS planes_usuarios (usuario_id INT PRIMARY KEY,plan_id INT NOT NULL,FOREIGN KEY(usuario_id) REFERENCES usuarios(id),FOREIGN KEY(plan_id) REFERENCES planes_servicio(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS archivos_usuario (id INT AUTO_INCREMENT PRIMARY KEY,usuario_id INT NOT NULL,nombre_original VARCHAR(200) NOT NULL,nombre_interno CHAR(48) NOT NULL UNIQUE,tamano_bytes BIGINT UNSIGNED NOT NULL,tipo VARCHAR(65) NOT NULL,creado_en TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(usuario_id) REFERENCES usuarios(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS tickets_soporte (id INT AUTO_INCREMENT PRIMARY KEY,usuario_id INT NOT NULL,asunto VARCHAR(150) NOT NULL,descripcion TEXT NOT NULL,estado ENUM('abierto','en_proceso','resuelto') NOT NULL DEFAULT 'abierto',creado_en TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(usuario_id) REFERENCES usuarios(id)) ENGINE=InnoDB;

-- ACTUALIZACION INTEGRADA (V5 + EXPEDIENTE V7)
-- Este mismo archivo sirve para una instalación nueva y para completar
-- tablas o columnas faltantes de versiones anteriores SIN borrar datos.
-- MariaDB de XAMPP admite ADD COLUMN IF NOT EXISTS.
ALTER TABLE pacientes
  ADD COLUMN IF NOT EXISTS sexo VARCHAR(30) NULL AFTER altura,
  ADD COLUMN IF NOT EXISTS domicilio VARCHAR(250) NULL AFTER sexo,
  ADD COLUMN IF NOT EXISTS ocupacion VARCHAR(120) NULL AFTER domicilio,
  ADD COLUMN IF NOT EXISTS contacto_emergencia_nombre VARCHAR(150) NULL AFTER ocupacion,
  ADD COLUMN IF NOT EXISTS contacto_emergencia_telefono VARCHAR(20) NULL AFTER contacto_emergencia_nombre;

-- Datos ampliados del perfil profesional; sin borrar registros existentes
ALTER TABLE medicos
 ADD COLUMN IF NOT EXISTS telefono_emergencia VARCHAR(20) NULL,
 ADD COLUMN IF NOT EXISTS domicilio VARCHAR(250) NULL,
 ADD COLUMN IF NOT EXISTS fecha_nacimiento DATE NULL,
 ADD COLUMN IF NOT EXISTS foto_perfil VARCHAR(60) NULL,
 ADD COLUMN IF NOT EXISTS cedula_documento VARCHAR(60) NULL,
 ADD COLUMN IF NOT EXISTS direccion_calle VARCHAR(100) NULL,
 ADD COLUMN IF NOT EXISTS direccion_numero_exterior VARCHAR(20) NULL,
 ADD COLUMN IF NOT EXISTS direccion_numero_interior VARCHAR(20) NULL,
 ADD COLUMN IF NOT EXISTS direccion_colonia VARCHAR(80) NULL,
 ADD COLUMN IF NOT EXISTS direccion_codigo_postal VARCHAR(5) NULL,
 ADD COLUMN IF NOT EXISTS direccion_municipio VARCHAR(80) NULL,
 ADD COLUMN IF NOT EXISTS direccion_estado VARCHAR(80) NULL;

