INSERT INTO citas(paciente_id,medico_id,consultorio_id,fecha,hora,estado) SELECT p.id,m.id,m.consultorio_id,DATE_ADD(CURDATE(),INTERVAL (7-WEEKDAY(CURDATE())) DAY),'10:00:00','programada' FROM pacientes p JOIN usuarios up ON up.id=p.usuario_id JOIN medicos m JOIN usuarios um ON um.id=m.usuario_id WHERE up.correo='paciente1@misalud.test' AND um.correo='medico1@misalud.test' AND NOT EXISTS (SELECT 1 FROM citas c WHERE c.paciente_id=p.id AND c.medico_id=m.id AND c.fecha=DATE_ADD(CURDATE(),INTERVAL (7-WEEKDAY(CURDATE())) DAY) AND c.hora='10:00:00');
